import { requireUser } from '@/lib/auth';
import { json, route, HttpError } from '@/lib/http';
import { getPatient } from '@/repos/patients';

/** The signed-in patient's own profile. */
export const GET = route(async (req) => {
  const user = await requireUser(req);
  if (user.role !== 'patient' || !user.patientId) throw new HttpError(403, 'forbidden');
  const p = await getPatient(user.patientId);
  if (!p) throw new HttpError(404, 'not_found');
  return json({
    id: p.id,
    firstName: p.first_name,
    lastName: p.last_name,
    dateOfBirth: p.date_of_birth,
    email: p.email,
    phone: p.phone,
  });
});
import { queryOne } from '@/lib/db';

export interface PatientRow {
  id: string;
  org_id: string;
  user_id: string | null;
  first_name: string;
  last_name: string;
  date_of_birth: Date;
  email: string | null;
  phone: string | null;
  mrn: string;
  reason_for_care: string | null;
  created_at: Date;
}

export async function getPatient(patientId: string): Promise<PatientRow | null> {
  return queryOne<PatientRow>('SELECT * FROM patients WHERE id = ?', [patientId]);
}

export async function getPatientByUserId(userId: string): Promise<PatientRow | null> {
  return queryOne<PatientRow>('SELECT * FROM patients WHERE user_id = ?', [userId]);
}
import { requireUser } from '@/lib/auth';
import { json, route, HttpError } from '@/lib/http';
import { audit } from '@/lib/audit';
import { hasActiveAccess } from '@/repos/careTeam';
import { getPatient } from '@/repos/patients';
import { listForPatient } from '@/repos/notes';

type Ctx = { params: Promise<{ patientId: string }> };

/** Chart view for a practitioner on the patient's care team. */
export const GET = route<Ctx>(async (req, { params }) => {
  const user = await requireUser(req);
  if (user.role !== 'practitioner' || !user.practitionerId) throw new HttpError(403, 'forbidden');
  const { patientId } = await params;
  const patient = await getPatient(patientId);
  if (!patient || patient.org_id !== user.orgId) throw new HttpError(404, 'not_found');
  if (!(await hasActiveAccess(user.practitionerId, patient.id))) throw new HttpError(403, 'forbidden');

  const notes = await listForPatient(patient.id);
  await audit(user, 'chart.view', 'patient', patient.id);
  return json({
    patient: {
      id: patient.id,
      firstName: patient.first_name,
      lastName: patient.last_name,
      dateOfBirth: patient.date_of_birth,
      mrn: patient.mrn,
      reasonForCare: patient.reason_for_care,
    },
    notes: notes.map((n) => ({ id: n.id, kind: n.kind, createdAt: n.created_at, body: n.body })),
  });
});
import { execute } from './db';
import type { CurrentUser } from './auth';

/** Records who did what to which record. Store ids only, never content. */
export async function audit(user: CurrentUser, action: string, targetType: string, targetId: string): Promise<void> {
  await execute(
    'INSERT INTO audit_log (user_id, action, target_type, target_id) VALUES (?, ?, ?, ?)',
    [user.id, action, targetType, targetId],
  );
}
import { describe, expect, it } from 'vitest';
import { GET } from '@/app/api/practitioner/patients/[patientId]/chart/route';
import { POST as REVOKE } from '@/app/api/admin/care-team/revoke/route';
import { call, TOKENS } from './helpers';

describe('practitioner chart', () => {
  it('shows clinical and psychotherapy notes to the treating practitioner', async () => {
    const res = await call(GET, { token: TOKENS.rosa, params: { patientId: 'pt_ava' } });
    expect(res.status).toBe(200);
    const kinds = res.json.notes.map((n: { kind: string }) => n.kind).sort();
    expect(kinds).toEqual(['clinical', 'clinical', 'psychotherapy']);
  });

  it('refuses a practitioner outside the care team', async () => {
    const res = await call(GET, { token: TOKENS.malik, params: { patientId: 'pt_ava' } });
    expect(res.status).toBe(403);
  });

  it('refuses a practitioner from another practice', async () => {
    const res = await call(GET, { token: TOKENS.hal, params: { patientId: 'pt_ava' } });
    expect(res.status).toBe(404);
  });
});

describe('POST /api/admin/care-team/revoke', () => {
  it('is for admins only', async () => {
